const $=id=>document.getElementById(id);
const day=(offset=0)=>{const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const labels={all:'Планы',today:'Сегодня'};
let view='today',showDone=false,editing=null;
let tasks=[{id:'1',title:'Купить продукты',date:day(),time:'19:00',done:false},{id:'2',title:'Записаться к стоматологу',date:day(),time:'',done:false},{id:'3',title:'Забрать заказ',date:day(),time:'20:00',done:false},{id:'4',title:'Оплатить интернет',date:day(7),time:'10:00',done:false},{id:'5',title:'Выбрать книгу',date:'',time:'',done:false},{id:'6',title:'Отправить документы',date:day(),time:'09:00',done:true},{id:'7',title:'Дейлик с командой',date:day(),time:'10:30',duration:30,done:false},{id:'8',title:'Ревью макетов главной',date:day(),time:'12:00',duration:90,done:false},{id:'9',title:'Созвон с разработкой',date:day(),time:'12:30',duration:60,done:false},{id:'10',title:'Обед',date:day(),time:'14:00',duration:60,done:false},{id:'11',title:'Спортзал',date:day(1),time:'08:00',duration:90,done:false},{id:'12',title:'1-1 с дизайнером',date:day(1),time:'15:00',duration:45,done:false},{id:'13',title:'Позвонить маме',date:day(1),time:'',done:false},{id:'14',title:'Презентация дизайн-системы',date:day(2),time:'11:00',duration:60,done:false},{id:'15',title:'Записать анимацию в Rive',date:day(2),time:'16:00',duration:120,done:false},{id:'16',title:'Забрать посылку',date:day(3),time:'',done:false},{id:'17',title:'Ужин с друзьями',date:day(4),time:'19:30',duration:150,done:false},{id:'18',title:'Продлить страховку',date:day(10),time:'',done:false},{id:'19',title:'Перформанс-ревью',date:day(14),time:'11:00',duration:120,done:false},{id:'20',title:'Разобрать бэклог идей',date:'',time:'',done:false},{id:'21',title:'Обновить портфолио',date:'',time:'',done:false}];
const matches=t=>view==='all'||(view==='today'&&t.date&&t.date===day());
function formatDate(d){return new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',...(d.slice(0,4)!==day().slice(0,4)?{year:'numeric'}:{})})}
function dateName(d){return d===day()?'Сегодня':d===day(1)?'Завтра':formatDate(d)}
function row(t){const el=document.createElement('div');el.className='task'+(t.done?' done':'');const check=document.createElement('button');check.className='check';check.setAttribute('aria-label',(t.done?'Вернуть задачу: ':'Завершить задачу: ')+t.title);check.setAttribute('aria-pressed',String(t.done));check.innerHTML='<span class="circle"></span>';check.onclick=()=>{t.done=!t.done;render()};const body=document.createElement('button');body.className='task-body';const title=document.createElement('span');title.className='task-name';title.textContent=t.title;body.append(title);const meta=document.createElement('span');meta.className='task-meta';meta.textContent=t.date?[(t.date<day()?'Просрочено · ':'')+dateName(t.date),t.time?`${t.time}–${clockLabel(timeMinutes(t.time)+taskDuration(t))}`:''].filter(Boolean).join(' · '):'Без даты';body.append(meta);body.onclick=()=>openEditor(t);el.append(check,body);return el}
function render(){document.querySelector(".app").dataset.view=view;const nav=$('navigation');nav.replaceChildren();for(const [key,label]of Object.entries(labels)){const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-pressed',String(key===view));if(key===view)b.setAttribute('aria-current','page');b.onclick=()=>{view=key;render()};nav.append(b)}$('heading').textContent=labels[view];$('dateLabel').textContent=new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});const active=tasks.filter(t=>matches(t)&&!t.done).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'99').localeCompare(b.time||'99'));$('total').textContent=active.length;$('tasks').replaceChildren();if(view==='today'){renderTimeline(active)}else{let last=null,groupContainer=null;for(const t of active){if(!groupContainer||(view!=='today'&&t.date!==last)){if(view!=='today'){const h=document.createElement('h2');h.className='group';h.textContent=t.date?dateName(t.date):'Без даты';$('tasks').append(h)}groupContainer=document.createElement('div');groupContainer.className='task-group';$('tasks').append(groupContainer);last=t.date}groupContainer.append(row(t))}if(!active.length){const empty=document.createElement('p');empty.className='empty';empty.textContent=view==='today'?'На сегодня задач нет':'Пока нет задач';$('tasks').append(empty)}}const done=tasks.filter(t=>matches(t)&&t.done);$('completedToggle').hidden=!done.length||view==='today';$('completedToggle').textContent=`${showDone?'−':'+'} Завершённые · ${done.length}`;$('completed').replaceChildren(...(showDone&&view!=='today'?done.map(row):[]))}
function openEditor(t){editing=t?.id||null;$('editorTitle').textContent=t?'Задача':'Новая задача';$('title').value=t?.title||'';$('date').value=t?.date||(t?'':view==='today'?day():'');$('time').value=t?.time||'';$('time').disabled=!$('date').value;$('delete').hidden=!t;$('completeEdit').hidden=!t;$('completeEdit').textContent=t?.done?'Вернуть в планы':'Отметить выполненной';$('endTime').value=t?.time?clockLabel(timeMinutes(t.time)+taskDuration(t)):'';syncEndTime();$('editor').showModal();setTimeout(()=>$('title').focus(),0)}
$('add').onclick=()=>openEditor();$('cancel').onclick=()=>$('editor').close();$('completedToggle').onclick=()=>{showDone=!showDone;render()};$('date').onchange=()=>{$('time').disabled=!$('date').value;if(!$('date').value)$('time').value=''};
document.querySelectorAll('[data-offset]').forEach(b=>b.onclick=()=>{$('date').value=day(Number(b.dataset.offset));$('time').disabled=false});$('clearDate').onclick=()=>{$('date').value='';$('time').value='';$('time').disabled=true};
$('form').onsubmit=e=>{e.preventDefault();syncEndTime();const title=$('title').value.trim();if(!title){$('title').setCustomValidity('Введите название задачи');$('title').reportValidity();return}const data={title,date:$('date').value,time:$('date').value?$('time').value:'',duration:$('date').value&&$('time').value?((timeMinutes($('endTime').value)-timeMinutes($('time').value)+1440)%1440||1440):30};if(editing)Object.assign(tasks.find(t=>t.id===editing),data);else tasks.push({id:(crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,"0")).join("")),done:false,...data});$('editor').close();if(!matches({...data}))view='all';render()};$('title').oninput=()=>$('title').setCustomValidity('');$('delete').onclick=()=>{tasks=tasks.filter(t=>t.id!==editing);$('editor').close();render()};$('timezone').textContent='Часовой пояс: '+Intl.DateTimeFormat().resolvedOptions().timeZone;
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_task_editor',description:'Открыть форму новой задачи в прототипе, без сохранения.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Ожидается пустой объект');openEditor();return{opened:true}}})}catch{}}

const timeMinutes=value=>{const [h,m]=value.split(':').map(Number);return h*60+m};
const clockLabel=minutes=>`${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;
const taskDuration=t=>t.duration||30;
function renderTimeline(active){
  const untimed=active.filter(t=>!t.time);
  if(untimed.length){const section=document.createElement('section');section.className='day-unscheduled';const title=document.createElement('h2');title.textContent='Без времени';const list=document.createElement('div');list.className='task-group';list.append(...untimed.map(row));section.append(title,list);$('tasks').append(section)}
  const scroll=document.createElement('div');scroll.className='timeline-scroll';scroll.tabIndex=0;scroll.setAttribute('aria-label','Расписание на сегодня, 00:00–24:00');
  const canvas=document.createElement('div');canvas.className='timeline';
  for(let h=0;h<=24;h++){const line=document.createElement('div');line.className='hour-line';line.style.top=`${h*96}px`;if(h===24){line.style.height='0';line.classList.add('last-hour')}const label=document.createElement('span');label.className='hour-label';label.textContent=`${String(h).padStart(2,'0')}:00`;line.append(label);canvas.append(line)}
  const entries=tasks.filter(t=>!t.done&&t.time&&(t.date===day()||(t.date===day(-1)&&timeMinutes(t.time)+taskDuration(t)>1440))).map(t=>{const rawStart=timeMinutes(t.time)+(t.date===day(-1)?-1440:0);return{t,start:Math.max(0,rawStart),end:Math.min(1440,rawStart+taskDuration(t))}}).sort((a,b)=>a.start-b.start||a.end-b.end);
  let cluster=[],clusterEnd=-1;
  function placeCluster(){const laneEnds=[];for(const e of cluster){let lane=laneEnds.findIndex(end=>end<=e.start);if(lane<0)lane=laneEnds.length;laneEnds[lane]=e.end;e.lane=lane}for(const e of cluster){const button=document.createElement('button');button.className='calendar-event'+(e.end-e.start<30?' short':'');button.style.top=`${e.start*1.6}px`;button.style.height=`${Math.max(1,(e.end-e.start)*1.6-2)}px`;button.style.left=`calc(${e.lane/laneEnds.length*100}% + 4px)`;button.style.width=`calc(${100/laneEnds.length}% - 8px)`;const title=document.createElement('strong');title.textContent=e.t.title;const time=document.createElement('small');time.textContent=`${e.t.time}–${clockLabel(timeMinutes(e.t.time)+taskDuration(e.t))}`;button.title=`${e.t.title}, ${time.textContent}`;button.setAttribute('aria-label',button.title);button.append(title,time);button.onclick=()=>openEditor(e.t);canvas.append(button)}cluster=[]}
  for(const e of entries){if(cluster.length&&e.start>=clusterEnd){placeCluster();clusterEnd=-1}cluster.push(e);clusterEnd=Math.max(clusterEnd,e.end)}if(cluster.length)placeCluster();
  const now=new Date();const marker=document.createElement('div');marker.className='current-time';marker.style.top=`${(now.getHours()*60+now.getMinutes())*1.6}px`;canvas.append(marker);scroll.append(canvas);$('tasks').append(scroll);

  requestAnimationFrame(()=>{scroll.scrollTop=Math.max(0,((entries[0]?.start??now.getHours()*60)-60)*1.6)});
}
function syncEndTime(){const enabled=Boolean($('date').value&&$('time').value);$('endTime').disabled=!enabled;if(!enabled){$('endTime').value='';$('endNote').textContent='';return}if(!$('endTime').value)$('endTime').value=clockLabel(timeMinutes($('time').value)+30);$('endNote').textContent=timeMinutes($('endTime').value)<=timeMinutes($('time').value)?'Окончание на следующий день':''}

$('time').addEventListener('change',()=>{$('endTime').value='';syncEndTime()});
$('endTime').addEventListener('change',syncEndTime);
$('date').addEventListener('change',syncEndTime);
$('clearDate').addEventListener('click',syncEndTime);
document.querySelectorAll('[data-offset]').forEach(b=>b.addEventListener('click',syncEndTime));
$('completeEdit').onclick=()=>{const t=tasks.find(t=>t.id===editing);if(t)t.done=!t.done;$('editor').close();render()};
render();
setInterval(()=>{const marker=document.querySelector(".current-time");if(marker){const now=new Date();marker.style.top=`${(now.getHours()*60+now.getMinutes())*1.6}px`}},60000);
{const f=document.querySelector('footer'),a=document.querySelector('.app');new ResizeObserver(()=>a.style.setProperty('--footer-h',`${f.offsetHeight-24}px`)).observe(f)}
